package io.spring.application;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import io.spring.application.CursorPager.Direction;
import io.spring.application.data.CommentData;
import io.spring.application.data.ProfileData;
import io.spring.core.user.User;
import io.spring.infrastructure.mybatis.readservice.CommentReadService;
import io.spring.infrastructure.mybatis.readservice.UserRelationshipQueryService;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.joda.time.DateTime;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class CommentQueryServiceCursorTest {

  @Mock private CommentReadService commentReadService;
  @Mock private UserRelationshipQueryService userRelationshipQueryService;

  // GreyTest trace: findByArticleIdWithCursor | IF-4-TRUE | BR-038 -> TP-035 -> TC-1106
  @Test
  void findByArticleIdWithCursor_WhenLimitIsZero_UsesDefaultLimit() {
    List<CommentData> expected = new ArrayList<>();
    for (int i = 70; i <= 89; i++) {
      expected.add(new CommentData("c" + i, "body " + i, "article-9", new DateTime(2024, 3, i - 69, 0, 0), null, new ProfileData("author-" + i, "user" + i, "", "", false)));
    }
    ArrayList<CommentData> comments = new ArrayList<>(expected);
    comments.add(new CommentData("c90", "body 90", "article-9", new DateTime(2024, 3, 21, 0, 0), null, new ProfileData("author-90", "user90", "", "", false)));
    User user = new User("viewer@example.com", "viewer", "secret", "", "");
    CursorPageParameter<DateTime> page = new CursorPageParameter<>(null, 0, Direction.NEXT);
    when(commentReadService.findByArticleIdWithCursor(eq("article-9"), eq(page))).thenReturn(comments);
    when(userRelationshipQueryService.followingAuthors(eq(user.getId()), anyList())).thenReturn(Collections.emptySet());
    CommentQueryService service = new CommentQueryService(commentReadService, userRelationshipQueryService);

    CursorPager<CommentData> result = service.findByArticleIdWithCursor("article-9", user, page);

    assertEquals(20, page.getLimit());
    assertEquals(expected, result.getData());
    assertFalse(result.getData().contains(comments.get(20)));
    assertTrue(result.hasNext());
    assertFalse(result.hasPrevious());
    verify(userRelationshipQueryService).followingAuthors(eq(user.getId()), anyList());
  }
}
